def rule(id,when,action,msg,page='3–4',source='nccp'):
 url=N if source=='nccp' else S
 RUL.append({'id':id,'priority':20,'when':when,'action':{'type':action,'components':['crizotinib'],'message':msg,'recommendation':msg},'source':{'document':'NCCP 00243 v7' if source=='nccp' else 'EMA Xalkori SmPC (adult NSCLC; supplemental source)','page':page,'url':url},'explanation':msg})
