rule('RENAL_EXACT30',eq('crizotinib_crcl_ml_min',30),'consultant_review','CrCl exactly 30 is omitted by NCCP >30/<30 table; EMA includes 30 in moderate renal impairment with no starting adjustment. Reconcile the source boundary with pharmacy.','3')
rule('DIALYSIS_REVIEW',any_(eq('dialysis'),eq('targeted_renal_band','dialysis')),'consultant_review','Dialysis: NCCP expects 250 mg once daily for haemodialysis, but EMA severe-renal dosing excludes haemodialysis/peritoneal dialysis. Seek specialist pharmacy plan; do not calculate a definite dose.','3')
