rule('QTC_FURTHER_RECURRENCE',eq('further_severe_qt_recurrence'),'permanently_discontinue','Further grade ≥3 QT recurrence after source modification: permanently discontinue.','3–4')
rule('BRADY_HOLD',any_(eq('bradycardia_symptomatic'),c('bradycardia_grade','>=',2)),'withhold','Symptomatic grade 2/3 or more severe bradycardia: withhold until grade ≤1 or heart rate ≥60. Review contributing/antihypertensive medicines. If a contributor is stopped/adjusted, grade 2/3 may resume previous dose; otherwise reduced-dose review.','4')
